CREATE PROCEDURE [purchase].[Purchase_AddPayment] @PurchaseInvoiceId UNIQUEIDENTIFIER,@MethodCode NVARCHAR(30),@Amount DECIMAL(18,2),@ReferenceNumber NVARCHAR(100)=NULL,@CreatedBy NVARCHAR(256)=NULL AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF @Amount<=0 THROW 51200,'Payment must be positive.',1;BEGIN TRAN;DECLARE @Method UNIQUEIDENTIFIER=(SELECT PaymentMethodId FROM sales.PaymentMethods WHERE MethodCode=@MethodCode AND IsActive=1),@Grand DECIMAL(18,2),@Paid DECIMAL(18,2);SELECT @Grand=GrandTotal,@Paid=PaidAmount FROM purchase.PurchaseInvoices WITH(UPDLOCK)WHERE PurchaseInvoiceId=@PurchaseInvoiceId AND IsDeleted=0 AND Status NOT IN('CANCELLED','DRAFT');IF @Method IS NULL OR @Grand IS NULL BEGIN ROLLBACK;THROW 51200,'Purchase or payment method not found.',1;END;IF @Paid+@Amount>@Grand BEGIN ROLLBACK;THROW 51200,'Payment exceeds outstanding balance.',1;END;INSERT purchase.PurchasePayments(PurchaseInvoiceId,PaymentMethodId,Amount,ReferenceNumber,CreatedBy)VALUES(@PurchaseInvoiceId,@Method,@Amount,@ReferenceNumber,@CreatedBy);UPDATE purchase.PurchaseInvoices SET PaidAmount=PaidAmount+@Amount,ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE PurchaseInvoiceId=@PurchaseInvoiceId;COMMIT;SELECT @PurchaseInvoiceId PurchaseInvoiceId,@Paid+@Amount PaidAmount,@Grand-@Paid-@Amount BalanceAmount;END;
